mode\": \"static\", \"endpoint\": null, \"attributes\": null}, \"classes\": \"govuk-radios\", \"disabled\": false, \"fieldset\": {\"legend\": {\"text\": \"Do you live in Canada?\", \"classes\": \"govuk-fieldset__legend--l\", \"isPageHeading\": false}}, \"formGroup\": {\"classes\": \"\"}, \"validation\": {\"rules\": [], \"required\": true, \"requiredMessage\": {\"en\": \"Please tell us if you live in Canada\"}}}','2025-09-18 13:21:37','2025-09-18 13:21:37'),(1438,112,3,2,'{\"id\": \"example-select\", \"hint\": {\"text\": {\"en\": \"\"}}, \"name\": \"example-select\", \"items\": [{\"text\": \"United States\", \"value\": \"usa\"}, {\"text\": \"Canada\", \"value\": \"canada\"}, {\"text\": \"France\", \"value\": \"france\"}, {\"text\": \"Japan\", \"value\": \"japan\"}, {\"text\": \"Brazil\", \"value\": \"brazil\"}, {\"text\": \"Australia\", \"value\": \"australia\"}, {\"text\": \"Germany\", \"value\": \"germany\"}, {\"text\": \"Italy\", \"value\": \"italy\"}, {\"text\": \"Mexico\", \"value\": \"mexico\"}, {\"text\": \"South Africa\", \"value\": \"south-africa\"}], \"label\": {\"text\": {\"en\": \"Country or Territory\"}, \"classes\": \"govuk-label--m\"}, \"classes\": \"govuk-select\", \"disabled\": false, \"formGroup\": {\"classes\": \"\"}, \"validation\": {\"rules\": [], \"required\": true, \"requiredMessage\": {\"en\": \"Select the country or territory you live in\"}}, \"errorMessage\": {\"text\": {\"en\": \"\"}}}','2025-09-18 13:21:37','2025-09-18 13:21:37'),(1444,113,1,1,'{\"id\": \"example-radio\", \"hint\": {\"text\": {\"en\": \"You can only choose one\"}}, \"name\": \"example-radio\", \"items\": [{\"text\": \"Yes\", \"value\": \"true\"}, {\"text\": \"No\", \"value\": \"false\", \"conditionalChildId\": \"1442_false_follow\"}], \"classes\": \"govuk-radios\", \"disabled\": false, \"fieldset\": {\"legend\": {\"text\": \"Have you had a Canadian passport before?\", \"classes\": \"govuk-fieldset__legend--l\", \"isPageHeading\": false}}, \"formGroup\": {\"classes\": \"\"}, \"validation\": {\"rules\": [], \"required\": true, \"requiredMessage\": {\"en\": \"Please tell us if you\'ve had a passport before\"}}}','2025-09-18 13:28:21','2025-09-18 13:28:21'),(1445,113,2,22,'{\"id\": \"1442_false_follow\", \"html\": \"\", \"name\": \"1442_false_follow\", \"text\": \"This section contains important background information.\", \"label\": {\"text\": \"You may need an interview\"}, \"classes\": \"\", \"fieldset\": {\"legend\": {\"text\": \"You may need an interview\", \"classes\": \"\", \"isPageHeading\": false}}}','2025-09-18 13:28:21','2025-09-18 13:28:21'),(1454,116,1,30,'{\"id\": \"panel\", \"html\": \"\", \"name\": \"panel\", \"classes\": \"\", \"titleText\": \"You live in Canada!\", \"headingLevel\": 1}','2025-09-23 15:47:54','2025-09-23 15:47:54'),(1456,115,1,30,'{\"id\": \"panel\", \"html\": \"\", \"name\": \"panel\", \"classes\": \"\", \"titleText\": \"You don\'t live in Canada!\", \"headingLevel\": 1}','2025-09-23 15:51:26','2025-09-23 15:51:26'),(1457,81,1,13,'{\"id\": \"example-date\", \"hint\": {\"text\": {\"en\": \"For example, 27 3 2007.  If you don\'t know it, leave it blank.\", \"fr\": \"Par exemple, 27 3 2007\"}}, \"name\": \"dob\", \"items\": [{\"name\": \"day\", \"classes\": \"govuk-input--width-2\", \"autocomplete\": \"bday-day\"}, {\"name\": \"month\", \"classes\": \"govuk-input--width-2\", \"autocomplete\": \"bday-month\"}, {\"name\": \"year\", \"classes\": \"govuk-input--width-4\", \"autocomplete\": \"bday-year\"}], \"classes\": \"\", \"disabled\": false, \"fieldset\": {\"legend\": {\"text\": {\"en\": \"What is your date of birth?\", \"fr\": \"Entrez la date\"}, \"classes\": \"govuk-fieldset__legend--l\", \"isPageHeading\": false}}, \"formGroup\": {\"classes\": \"\"}, \"autocompletePreset\": \"dob\"}','2025-09-25 16:41:12','2025-09-25 16:41:12'),(1458,118,1,31,'{\"id\": \"example-character-count\", \"hint\": {\"text\": {\"en\": \"Do not include personal information.\"}}, \"name\": \"example-character-count\", \"rows\": 5, \"label\": {\"text\": {\"en\": \"Describe your request\", \"fr\": \"Champ avec compteur de caractères\"}, \"classes\": \"govuk-label--m\"}, \"value\": {\"en\": \"\"}, \"classes\": \"\", \"maxwords\": \"\", \"formGroup\": {\"classes\": \"\"}, \"maxlength\": 200, \"threshold\": 75, \"spellcheck\": true, \"autocomplete\": \"\", \"errorMessage\": {\"text\": {\"en\": \"\"}}}','2025-09-28 16:48:29','2025-09-28 16:48:29'),(1459,119,1,1,'{\"id\": \"example-radio\", \"hint\": {\"text\": {\"en\": \"You can only choose one\"}}, \"name\": \"example-radio\", \"items\": [{\"text\": \"Option 1\", \"value\": \"1\"}, {\"text\": \"Option 2\", \"value\": \"2\"}, {\"text\": \"Option 3\", \"value\": \"3\"}], \"classes\": \"govuk-radios\", \"disabled\": false, \"fieldset\": {\"legend\": {\"text\": \"Choose an option\", \"classes\": \"govuk-fieldset__legend--l\", \"isPageHeading\": false}}, \"formGroup\": {\"classes\": \"\"}}','2025-09-28 17:16:33','2025-09-28 17:16:33'),(1471,121,1,29,'{\"id\": \"text-block\", \"html\": \"\", \"name\": \"text-block\", \"text\": {\"en\": \"Submission\", \"fr\": \"Soumission\"}, \"classes\": \"govuk-heading-l\"}','2025-09-29 11:39:17','2025-09-29 11:39:17'),(1472,121,2,29,'{\"id\": \"text-block-2\", \"html\": \"\", \"name\": \"text-block-2\", \"text\": {\"en\": \"You are now ready to submit your application. Please read the following legal declaration carfully and indicate that your acceptance with a signature below.   When you hit submit the application will be sent to NWAC and you will recieve a confimation email detailing next steps.   You can sign back into your dashbaord to check status and contact the case-workers.\", \"fr\": \"Vous êtes maintenant prêt à soumettre votre demande. Veuillez lire attentivement la déclaration légale suivante et indiquer votre acceptation par une signature ci-dessous. Lorsque vous appuierez sur soumettre, la demande sera envoyée à l\'ANFNC et vous recevrez un courriel de confirmation détaillant les prochaines étapes. Vous pouvez vous reconnecter à votre tableau de bord pour vérifier le statut et contacter les intervenants.\"}, \"classes\": \"govuk-hint\"}','2025-09-29 11:39:17','2025-09-29 11:39:17'),(1473,121,3,29,'{\"id\": \"text-block-3\", \"html\": \"\", \"name\": \"text-block-3\", \"text\": {\"en\": \"I, the undersigned, give my expressed and informed consent to the Native Women’s Association of Canada and/or its sub-agreement holders to the Indigenous Skills and Employment Training Program (hereinafter referred to as ISET), to collect personal or sensitive information as it relates to my request for funding under the ISET program funded by Employment and Social Development Canada (ESDC). My consent extends to providing my Social Insurance Number (SIN), to determine my eligibility for interventions such as skills training and wage subsidies as part of the Labour Market Development Agreements (LMDA) program.\", \"fr\": \"Je, le soussigné, donne mon consentement exprimé et éclairé à l’Association des femmes autochtones du Canada et/ou à ses titulaires de sous-accords du Programme de formation et de perfectionnement des compétences autochtones (ci-après dénommé ISET), pour recueillir des renseignements personnels ou sensibles en lien avec ma demande de financement dans le cadre du programme ISET financé par Emploi et Développement social Canada (EDSC). Mon consentement s’étend à la fourniture de mon numéro d’assurance sociale (NAS), afin de déterminer mon admissibilité à des interventions telles que la formation professionnelle et les subventions salariales dans le cadre du programme des ententes de développement du marché du travail (EDMT).\"}, \"classes\": \"govuk-body\"}','2025-09-29 11:39:17','2025-09-29 11:39:17'),(1474,121,4,29,'{\"id\": \"text-block-4\", \"html\": \"\", \"name\": \"text-block-4\", \"text\": {\"en\": \"I acknowledge that the information is collected and administered in accordance with the Privacy Act (R.S.C. 1985, c P-21), the Department Employment and Social Development Canada Act (S.C. 2005, c.34), and the Access to Information Act (R.S.C., 1985, c.A-1). Information collected is to be used to determine eligibility for the ISET program; to measure results of this Agreement and evaluate its success; evaluate the effectiveness of the Program in achieving its objective; and, to meet its obligations of accountability by reporting on the results of the Program.\", \"fr\": \"Je reconnais que les renseignements sont recueillis et administrés conformément à la Loi sur la protection des renseignements personnels (L.R.C. 1985, ch. P-21), la Loi sur le ministère de l’Emploi et du Développement social Canada (L.C. 2005, ch. 34) et la Loi sur l’accès à l’information (L.R.C., 1985, ch. A-1). Les renseignements recueillis serviront à déterminer l’admissibilité au programme ISET; à mesurer les résultats de la présente entente et à en évaluer le succès; à évaluer l’efficacité du programme dans l’atteinte de ses objectifs; et à remplir ses obligations de reddition de comptes en faisant rapport des résultats du programme.\"}, \"classes\": \"govuk-body\"}','2025-09-29 11:39:17','2025-09-29 11:39:17'),(1475,121,5,29,'{\"id\": \"text-block-5\", \"html\": \"\", \"name\": \"text-block-5\", \"text\": {\"en\": \"All information referred to above shall be treated as confidential, and the Native Women’s Association of Canada and its sub-agreement holders will take all security measures reasonably necessary for the protection of such information against unauthorized release or disclosure.\", \"fr\": \"Tous les renseignements mentionnés ci-dessus seront traités de manière confidentielle, et l’Association des femmes autochtones du Canada ainsi que ses titulaires de sous-accords prendront toutes les mesures de sécurité raisonnablement nécessaires pour protéger ces renseignements contre toute diffusion ou divulgation non autorisée.\"}, \"classes\": \"govuk-body\"}','2025-09-29 11:39:17','2025-09-29 11:39:17'),(1476,121,6,29,'{\"id\": \"text-block-6\", \"html\": \"\", \"name\": \"text-block-6\", \"text\": {\"en\": \"I understand that my personal information shall not be used or disclosed for purposes other than those for which it was collected, except with the expressed consent of you, as the client, or as required by law. Personal information shall be retained only as long as necessary for the fulfilment of those purposes.\", \"fr\": \"Je comprends que mes renseignements personnels ne seront pas utilisés ou divulgués à d’autres fins que celles pour lesquelles ils ont été recueillis, sauf avec mon consentement exprès, en tant que client, ou si la loi l’exige. Les renseignements personnels ne seront conservés que pour la durée nécessaire à la réalisation de ces fins.\"}, \"classes\": \"govuk-body\"}','2025-09-29 11:39:17','2025-09-29 11:39:17'),(1477,121,7,29,'{\"id\": \"text-block-7\", \"html\": \"\", \"name\": \"text-block-7\", \"text\": {\"en\": \"I understand that the funding opportunity for which I am being considered is intended to increase Indigenous participation in the Canadian labour market and support First Nations, Metis and Inuit peoples’ access to sustainable and meaningful employment; and, provides access to training and employment supports to all Indigenous women in all their gender diversity, in Canada including status and non-status First Nations, Metis and Inuit peoples whether residing on or off-reserve, in urban centres and in rural, remote communities.\", \"fr\": \"Je comprends que l’occasion de financement pour laquelle je suis considéré vise à accroître la participation des Autochtones au marché du travail canadien et à soutenir l’accès des Premières Nations, des Métis et des Inuits à un emploi durable et significatif; et qu’elle offre un accès à la formation et aux soutiens à l’emploi à toutes les femmes autochtones dans toute leur diversité de genre, au Canada, y compris les membres des Premières Nations avec ou sans statut, les Métis et les Inuits, qu’elles résident dans des réserves, des centres urbains ou des collectivités rurales et éloignées.\"}, \"classes\": \"govuk-body\"}','2025-09-29 11:39:17','2025-09-29 11:39:17'),(1478,121,8,29,'{\"id\": \"text-block-8\", \"html\": \"\", \"name\": \"text-block-8\", \"text\": {\"en\": \"I understand that providing false or misleading information and/or omission of information by me about my Indigenous identity may result in an investigation and if the investigation is founded, will be grounds for immediate suspension of any funding and further, revocation of any Funding Agreement between me and the Native Women’s Association of Canada and/or its sub-agreement holders, and will result in a repayment of funds to Employment and Social Development Canada (ESDC), for monies I received to which I was not entitled.\", \"fr\": \"Je comprends que la fourniture de renseignements faux ou trompeurs et/ou l’omission de renseignements par moi concernant mon identité autochtone peut entraîner une enquête et, si l’enquête est fondée, constitueront un motif de suspension immédiate de tout financement et, de plus, de révocation de toute entente de financement entre moi et l’Association des femmes autochtones du Canada et/ou ses titulaires de sous-accords, et entraîneront le remboursement des fonds à Emploi et Développement social Canada (EDSC), pour les montants que j’ai reçus et auxquels je n’avais pas droit.\"}, \"classes\": \"govuk-body\"}','2025-09-29 11:39:17','2025-09-29 11:39:17'),(1479,121,9,29,'{\"id\": \"text-block-9\", \"html\": \"\", \"name\": \"text-block-9\", \"text\": {\"en\": \"I declare that I am an Indigenous person according to the following definition: Indigenous Peoples are people who are First Nations, Inuit or Métis.\", \"fr\": \"Je déclare que je suis une personne autochtone selon la définition suivante : Les peuples autochtones sont les personnes qui sont Premières Nations, Inuits ou Métis.\"}, \"classes\": \"govuk-body\"}','2025-09-29 11:39:17','2025-09-29 11:39:17'),(1480,121,10,35,'{\"id\": \"applicant_signature\", \"hint\": {\"text\": {\"en\": \"Enter your full legal name then press Sign.\", \"fr\": \"Entrez votre nom légal complet, puis appuyez sur Signer.\"}}, \"name\": \"applicant_signature\", \"label\": {\"text\": {\"en\": \"Type your full name to sign\", \"fr\": \"Tapez votre nom complet pour signer\"}, \"classes\": \"govuk-label--m\"}, \"required\": true, \"formGroup\": {\"classes\": \"\"}, \"boxPadding\": \"m\", \"clearLabel\": {\"text\": {\"en\": \"Clear\", \"fr\": \"Effacer\"}}, \"actionLabel\": {\"text\": {\"en\": \"Sign Now\", \"fr\": \"Signer maintenant\"}}, \"placeholder\": {\"text\": {\"en\": \"First Last\", \"fr\": \"Prénom Nom\"}}, \"handwritingFont\": \"cursive\", \"statusSignedText\": {\"text\": {\"en\": \"Signed\", \"fr\": \"Signé\"}}, \"statusUnsignedText\": {\"text\": {\"en\": \"Not signed\", \"fr\": \"Non signé\"}}}','2025-09-29 11:39:17','2025-09-29 11:39:17'),(1525,83,1,29,'{\"id\": \"text-block\", \"html\": \"\", \"name\": \"text-block\", \"text\": {\"en\": \"Contact Information\", \"fr\": \"Coordonnées\"}, \"classes\": \"govuk-heading-l\"}','2025-10-01 08:27:05','2025-10-01 08:27:05'),(1526,83,2,29,'{\"id\": \"text-block-2\", \"html\": \"\", \"name\": \"text-block-2\", \"text\": {\"en\": \"Provide your contact details so we can reach you during the application process.\", \"fr\": \"Fournissez vos coordonnées afin que nous puissions vous joindre pendant le processus de demande.\"}, \"classes\": \"govuk-body-l\"}','2025-10-01 08:27:05','2025-10-01 08:27:05'),(1527,83,3,26,'{\"id\": \"example-input\", \"hint\": {\"text\": {\"en\": \"Include apartment or unit number if applicable\", \"fr\": \"Incluez le numéro d\'appartement ou d\'unité, si applicable\"}}, \"name\": \"address-street-address\", \"type\": \"text\", \"label\": {\"text\": {\"en\": \"Street Address\", \"fr\": \"Adresse\"}, \"classes\": \"govuk-label--s\"}, \"value\": {\"en\": \"\"}, \"prefix\": {\"text\": \"\"}, \"suffix\": {\"text\": \"\"}, \"classes\": \"govuk-input\", \"pattern\": \"\", \"formGroup\": {\"classes\": \"\"}, \"inputmode\": \"\", \"spellcheck\": false, \"validation\": {\"rules\": [], \"required\": true}, \"autocomplete\": \"street-address\", \"errorMessage\": {\"text\": {\"en\": \"\"}}}','2025-10-01 08:27:05','2025-10-01 08:27:05'),(1528,83,4,26,'{\"id\": \"example-input-2\", \"hint\": {\"text\": {\"en\": \"\"}}, \"name\": \"address-city\", \"type\": \"text\", \"label\": {\"text\": {\"en\": \"City\", \"fr\": \"Ville\"}, \"classes\": \"govuk-label--s\"}, \"value\": {\"en\": \"\"}, \"prefix\": {\"text\": \"\"}, \"suffix\": {\"text\": \"\"}, \"classes\": \"govuk-input\", \"pattern\": \"\", \"formGroup\": {\"classes\": \"\"}, \"inputmode\": \"\", \"spellcheck\": false, \"validation\": {\"rules\": [], \"required\": true}, \"autocomplete\": \"address-level2\", \"errorMessage\": {\"text\": {\"en\": \"\"}}}','2025-10-01 08:27:05','2025-10-01 08:27:05'),(1529,83,5,2,'{\"id\": \"address-province\", \"hint\": {\"text\": {\"en\": \"Select which provice or territory you live in.\", \"fr\": \"Sélectionnez la province ou le territoire où vous résidez.\"}}, \"name\": \"address-province\", \"items\": [{\"text\": {\"en\": \"Alberta\", \"fr\": \"Alberta\"}, \"value\": \"ab\"}, {\"text\": {\"en\": \"Manitoba\", \"fr\": \"Manitoba\"}, \"value\": \"mb\"}, {\"text\": {\"en\": \"New Brunswick\", \"fr\": \"Nouveau-Brunswick\"}, \"value\": \"nb\"}, {\"text\": {\"en\": \"Newfoundland and Labrador\", \"fr\": \"Terre-Neuve-et-Labrador\"}, \"value\": \"nl\"}, {\"text\": {\"en\": \"Northwest Territories\", \"fr\": \"Territoires du Nord-Ouest\"}, \"value\": \"nt\"}, {\"text\": {\"en\": \"Nunavut\", \"fr\": \"Nunavut\"}, \"value\": \"nu\"}, {\"text\": {\"en\": \"Ontario\", \"fr\": \"Ontario\"}, \"value\": \"on\"}, {\"text\": {\"en\": \"Prince Edward Island\", \"fr\": \"Île-du-Prince-Édouard\"}, \"value\": \"pe\"}, {\"text\": {\"en\": \"Quebec\", \"fr\": \"Québec\"}, \"value\": \"qc\"}, {\"text\": {\"en\": \"Saskatchewan\", \"fr\": \"Saskatchewan\"}, \"value\": \"sk\"}, {\"text\": {\"en\": \"Nova Scotia\", \"fr\": \"Nouvelle-Écosse\"}, \"value\": \"ns\"}, {\"text\": {\"en\": \"Yukon Territory\", \"fr\": \"Territoire du Yukon\"}, \"value\": \"yt\"}], \"label\": {\"text\": {\"en\": \"Province or Territory\", \"fr\": \"Province ou territoire\"}, \"classes\": \"govuk-label--s\"}, \"props\": {\"mode\": \"static\", \"endpoint\": null, \"attributes\": null}, \"validation\": {\"rules\": [], \"required\": true}}','2025-10-01 08:27:05','2025-10-01 08:27:05'),(1530,83,6,26,'{\"id\": \"example-input-3\", \"hint\": {\"text\": {\"en\": \"\"}}, \"mask\": \"postal-code-ca\", \"name\": \"address-postcode\", \"type\": \"text\", \"label\": {\"text\": {\"en\": \"Postal Code\", \"fr\": \"Code postal\"}, \"classes\": \"govuk-label--s\"}, \"value\": {\"en\": \"\"}, \"prefix\": {\"text\": \"\"}, \"suffix\": {\"text\": \"\"}, \"classes\": \"govuk-input\", \"pattern\": \"\", \"formGroup\": {\"classes\": \"\"}, \"inputmode\": \"\", \"spellcheck\": true, \"validation\": {\"rules\": [], \"required\": false}, \"autocomplete\": \"postal-code\", \"errorMessage\": {\"text\": {\"en\": \"\"}}}','2025-10-01 08:27:05','2025-10-01 08:27:05'),(1531,83,7,26,'{\"id\": \"example-input-4\", \"hint\": {\"text\": {\"en\": \"Include area code (e.g., 613-555-1234).\", \"fr\": \"Incluez l\'indicatif régional (ex., 613-555-1234).\"}}, \"mask\": \"phone-na\", \"name\": \"telephone-day\", \"type\": \"tel\", \"label\": {\"text\": {\"en\": \"Daytime Phone Number\", \"fr\": \"Numéro de téléphone en journée\"}, \"classes\": \"govuk-label--s\"}, \"value\": {\"en\": \"\"}, \"prefix\": {\"text\": \"\"}, \"suffix\": {\"text\": \"\"}, \"classes\": \"govuk-input\", \"pattern\": \"\", \"formGroup\": {\"classes\": \"\"}, \"inputmode\": \"tel\", \"spellcheck\": false, \"autocomplete\": \"tel\", \"errorMessage\": {\"text\": {\"en\": \"\"}}}','2025-10-01 08:27:05','2025-10-01 08:27:05'),(1532,83,8,26,'{\"id\": \"example-input-6\", \"hint\": {\"text\": {\"en\": \"We will use this to contact you about your application.\", \"fr\": \"Nous utiliserons cette adresse pour vous contacter au sujet de votre demande.\"}}, \"name\": \"contact-email-address\", \"type\": \"email\", \"label\": {\"text\": {\"en\": \"Email Address\", \"fr\": \"Adresse courriel\"}, \"classes\": \"govuk-label--s\"}, \"value\": {\"en\": \"\"}, \"prefix\": {\"text\": \"\"}, \"suffix\": {\"text\": \"\"}, \"classes\": \"govuk-input\", \"pattern\": \"\", \"formGroup\": {\"classes\": \"\"}, \"inputmode\": \"email\", \"spellcheck\": false, \"autocomplete\": \"email\", \"errorMessage\": {\"text\": {\"en\": \"\"}}}','2025-10-01 08:27:05','2025-10-01 08:27:05'),(1533,83,9,26,'{\"id\": \"example-input-5\", \"hint\": {\"text\": {\"en\": \"Include area code.\", \"fr\": \"Incluez l\'indicatif régional.\"}}, \"mask\": \"phone-na\", \"name\": \"telephone-alt\", \"type\": \"tel\", \"label\": {\"text\": {\"en\": \"Alternative Phone Number (optional)\", \"fr\": \"Numéro de téléphone alternatif (facultatif)\"}, \"classes\": \"govuk-label--s\"}, \"value\": {\"en\": \"\"}, \"prefix\": {\"text\": \"\"}, \"suffix\": {\"text\": \"\"}, \"classes\": \"govuk-input\", \"pattern\": \"\", \"formGroup\": {\"classes\": \"\"}, \"inputmode\": \"tel\", \"spellcheck\": true, \"validation\": {\"rules\": [], \"required\": false}, \"autocomplete\": \"\", \"errorMessage\": {\"text\": {\"en\": \"\"}}}','2025-10-01 08:27:05','2025-10-01 08:27:05'),(1534,83,10,32,'{\"id\": \"example-textarea\", \"hint\": {\"text\": {\"en\": \"Leave blank if your mailing address is the same as your street address.\", \"fr\": \"N\'incluez pas d\'informations personnelles ou financières.\"}}, \"name\": \"address-mailing-address\", \"rows\": 5, \"label\": {\"text\": {\"en\": \"Mailing Address (if different)\", \"fr\": \"Champ multi-lignes\"}, \"classes\": \"govuk-label--s\"}, \"value\": {\"en\": \"\"}, \"classes\": \"govuk-textarea\", \"formGroup\": {\"classes\": \"\"}, \"spellcheck\": false, \"autocomplete\": \"mailing_address\", \"errorMessage\": {\"text\": {\"en\": \"\"}}}','2025-10-01 08:27:05','2025-10-01 08:27:05'),(1560,122,1,29,'{\"id\": \"text-block\", \"html\": \"\", \"name\": \"text-block\", \"text\": {\"en\": \"1\", \"fr\": \"Exemple de texte\"}, \"classes\": \"govuk-body\"}','2025-10-07 12:20:32','2025-10-07 12:20:32'),(1561,122,2,26,'{\"id\": \"example-input\", \"hint\": {\"text\": {\"en\": \"This is my hint text\", \"fr\": \"Ceci est mon texte d\'indice\"}}, \"mask\": \"\", \"name\": \"example-input\", \"type\": \"text\", \"label\": {\"text\": {\"en\": \"2\", \"fr\": \"Ceci est mon test\"}, \"classes\": \"govuk-label--m\"}, \"value\": {\"en\": \"\"}, \"prefix\": {\"text\": \"\"}, \"suffix\": {\"text\": \"\"}, \"classes\": \"govuk-input\", \"pattern\": \"\", \"formGroup\": {\"classes\": \"\"}, \"inputmode\": \"\", \"spellcheck\": true, \"autocomplete\": \"\", \"errorMessage\": {\"text\": {\"en\": \"\"}}}','2025-10-07 12:20:32','2025-10-07 12:20:32'),(1562,122,3,2,'{\"id\": \"example-select\", \"hint\": {\"text\": {\"en\": \"Select the applicable option.\"}}, \"name\": \"example-select\", \"items\": [{\"text\": \"-- Select --\", \"value\": \"\"}, {\"text\": \"Option 1\", \"value\": \"opt1\"}, {\"text\": \"Option 2\", \"value\": \"opt2\"}], \"label\": {\"text\": {\"en\": \"3\"}, \"classes\": \"govuk-label--m\"}, \"classes\": \"govuk-select\", \"disabled\": false, \"formGroup\": {\"classes\": \"\"}, \"errorMessage\": {\"text\": {\"en\": \"\"}}}','2025-10-07 12:20:32','2025-10-07 12:20:32'),(1563,122,4,13,'{\"id\": \"example-date\", \"hint\": {\"text\": {\"en\": \"For example, 27 3 2007\", \"fr\": \"Par exemple, 27 3 2007\"}}, \"name\": \"example-date\", \"items\": [{\"name\": \"day\", \"classes\": \"govuk-input--width-2\"}, {\"name\": \"month\", \"classes\": \"govuk-input--width-2\"}, {\"name\": \"year\", \"classes\": \"govuk-input--width-4\"}], \"classes\": \"\", \"disabled\": false, \"fieldset\": {\"legend\": {\"text\": {\"en\": \"4\", \"fr\": \"Entrez la date\"}, \"classes\": \"g